  var m = String(a.price).match(/^od ([\d\s ]+Kč)(.*)$/);
  return m ? '<span class="price-from"><small>od</small> ' + esc(m[1]) + ' <small>' + esc(m[2].replace(/^\s*\/\s*/, '/ ')) + '</small></span>' : '<span class="price-from">' + esc(a.price) + '</span>';
